class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        count = 0
        for num in range(l, r + 1):
            digits = [int(d) for d in str(num)]
            digit_sum = sum(digits)
            digit_product = 1
            for d in digits:
                digit_product *= d
            if digit_product % digit_sum == 0:
                count += 1
        return count

from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        available = list(range(1, n + 1))

        def count_from_position(start_idx, required_parity):
            """Count permutations starting from index start_idx with required parity at that position."""
            if start_idx >= len(available):
                return 1

            count = 0
            for i in range(start_idx, len(available)):
                if available[i] % 2 == required_parity:
                    count += 1

            if count == 0:
                return 0

            # Swap current element to position start_idx
            available[start_idx], available[i] = available[i], available[start_idx]
            saved = available[start_idx]

            result = count * count_from_position(start_idx + 1, 1 - required_parity)

            # Restore
            available[start_idx] = saved
            # Find saved's original position
            for j in range(start_idx + 1, len(available)):
                if available[j] == saved:
                    available[start_idx], available[j] = available[j], available[start_idx]
                    break

            return result

        # Find which element is first
        first = -1
        for v in range(1, n + 1):
            required_parity = v % 2
            count = count_from_position(0, required_parity)
            if k <= count:
                first = v
                break
            k -= count

        if first == -1:
            return []

        # Build the permutation
        result = [first]
        available = list(range(1, n + 1))
        available.remove(first)

        for pos in range(1, n):
            required_parity = 1 - (result[-1] % 2)
            # Find k-th available element with required parity
            for i in range(len(available)):
                if available[i] % 2 == required_parity:
                    count = count_from_position(0, required_parity)
                    if k <= count:
                        result.append(available[i])
                        available.pop(i)
                        break
                    k -= count

        return result

import sys

def solve():
    MOD = 998244353
    M = MOD - 1  # 998244352
    data = sys.stdin.buffer.read().split()
    it = iter(data)
    H = int(next(it))
    W = int(next(it))
    N = H * W
    A = [0] * N
    for i in range(N):
        A[i] = int(next(it)) % MOD
    Q = int(next(it))
    sh = int(next(it))
    sw = int(next(it))

    # Precompute count1_modM: number of paths from (1,1) to (i,j) mod M
    count1 = [0] * N
    for h in range(1, H + 1):
        for w in range(1, W + 1):
            idx = (h - 1) * W + (w - 1)
            if h == 1 and w == 1:
                count1[idx] = 1
            elif h == 1:
                count1[idx] = count1[(h - 1) * W + (w - 2)]
            elif w == 1:
                count1[idx] = count1[(h - 2) * W + (w - 1)]
            else:
                up_idx = (h - 2) * W + (w - 1)
                left_idx = (h - 1) * W + (w - 2)
                count1[idx] = (count1[up_idx] + count1[left_idx]) % M

    # Precompute count2_modM: number of paths from (i,j) to (H,W) mod M
    count2 = [0] * N
    for h in range(H, 0, -1):
        for w in range(W, 0, -1):
            idx = (h - 1) * W + (w - 1)
            if h == H and w == W:
                count2[idx] = 1
            elif h == H:
                count2[idx] = count2[(h - 1) * W + w]  # (h, w+1) -> idx+1
            elif w == W:
                count2[idx] = count2[h * W + (w - 1)]  # (h+1, w) -> idx+W
            else:
                down_idx = h * W + (w - 1)  # (h+1, w)
                right_idx = (h - 1) * W + w  # (h, w+1)
                count2[idx] = (count2[down_idx] + count2[right_idx]) % M

    # Compute weight_modM for each cell
    weight = [0] * N
    for i in range(N):
        weight[i] = count1[i] * count2[i] % M

    # Initial product and zero count
    prod = 1
    count_zero = 0
    for i in range(N):
        if A[i] == 0:
            count_zero += 1
        else:
            prod = prod * pow(A[i], weight[i], MOD) % MOD

    # Process queries
    out_lines = []
    for _ in range(Q):
        d = next(it).decode()
        a = int(next(it)) % MOD
        if d == 'L':
            sw -= 1
        elif d == 'R':
            sw += 1
        elif d == 'U':
            sh -= 1
        elif d == 'D':
            sh += 1
        idx = (sh - 1) * W + (sw - 1)
        old = A[idx]
        A[idx] = a
        if old == a:
            pass
        elif old == 0 and a != 0:
            prod = prod * pow(a, weight[idx], MOD) % MOD
            count_zero -= 1
        elif old != 0 and a == 0:
            inv_old = pow(old, MOD - 2, MOD)
            prod = prod * pow(inv_old, weight[idx], MOD) % MOD
            count_zero += 1
        else:  # old != 0 and a != 0
            inv_old = pow(old, MOD - 2, MOD)
            factor = pow(a * inv_old % MOD, weight[idx], MOD)
            prod = prod * factor % MOD

        if count_zero > 0:
            out_lines.append('0')
        else:
            out_lines.append(str(prod))

    sys.stdout.write('\n'.join(out_lines))

if __name__ == "__main__":
    solve()

