import bisect

def solve():
    data = sys.stdin.buffer.read().split()
    it = iter(data)
    N = int(next(it))
    M = int(next(it))
    Sx = int(next(it))
    Sy = int(next(it))

    # Group houses by rows and columns using sorted lists
    # row_map: y -> sorted list of x
    # col_map: x -> sorted list of y
    row_map = {}
    col_map = {}
    for _ in range(N):
        x = int(next(it))
        y = int(next(it))
        if y not in row_map:
            row_map[y] = []
        row_map[y].append(x)
        if x not in col_map:
            col_map[x] = []
        col_map[x].append(y)

    # Sort the lists for binary search
    for y in row_map:
        row_map[y].sort()
    for x in col_map:
        col_map[x].sort()

    x, y = Sx, Sy
    visited = 0

    for _ in range(M):
        d = next(it).decode()
        c = int(next(it))
        if d == 'L':
            x_new = x - c
            lo = min(x, x_new)
            hi = max(x, x_new)
            if y in row_map:
                lst = row_map[y]
                # Find indices
                left = bisect.bisect_left(lst, lo)
                right = bisect.bisect_right(lst, hi)
                if left < right:
                    # These houses are visited
                    count = right - left
                    visited += count
                    # For each house in this range, remove from col_map
                    for i in range(left, right):
                        hx = lst[i]
                        if hx in col_map:
                            col_lst = col_map[hx]
                            # Remove y from col_lst
                            idx = bisect.bisect_left(col_lst, y)
                            if idx < len(col_lst) and col_lst[idx] == y:
                                col_lst.pop(idx)
                                if not col_lst:
                                    del col_map[hx]
                    # Remove the range from row_map[y]
                    row_map[y] = lst[:left] + lst[right:]
                    if not row_map[y]:
                        del row_map[y]
            x = x_new
        elif d == 'R':
            x_new = x + c
            lo = min(x, x_new)
            hi = max(x, x_new)
            if y in row_map:
                lst = row_map[y]
                left = bisect.bisect_left(lst, lo)
                right = bisect.bisect_right(lst, hi)
                if left < right:
                    count = right - left
                    visited += count
                    for i in range(left, right):
                        hx = lst[i]
                        if hx in col_map:
                            col_lst = col_map[hx]
                            idx = bisect.bisect_left(col_lst, y)
                            if idx < len(col_lst) and col_lst[idx] == y:
                                col_lst.pop(idx)
                                if not col_lst:
                                    del col_map[hx]
                    row_map[y] = lst[:left] + lst[right:]
                    if not row_map[y]:
                        del row_map[y]
            x = x_new
        elif d == 'U':
            y_new = y + c
            lo = min(y, y_new)
            hi = max(y, y_new)
            if x in col_map:
                lst = col_map[x]
                left = bisect.bisect_left(lst, lo)
                right = bisect.bisect_right(lst, hi)
                if left < right:
                    count = right - left
                    visited += count
                    for i in range(left, right):
                        hy = lst[i]
                        if hy in row_map:
                            row_lst = row_map[hy]
                            idx = bisect.bisect_left(row_lst, x)
                            if idx < len(row_lst) and row_lst[idx] == x:
                                row_lst.pop(idx)
