                                    del row_map[hy]
                    col_map[x] = lst[:left] + lst[right:]
                    if not col_map[x]:
                        del col_map[x]
            y = y_new
        elif d == 'D':
            y_new = y - c
            lo = min(y, y_new)
            hi = max(y, y_new)
            if x in col_map:
                lst = col_map[x]
                left = bisect.bisect_left(lst, lo)
                right = bisect.bisect_right(lst, hi)
