class Solution:
    def makeStringGood(self, s: str) -> int:
        from collections import Counter

        n = len(s)
        count = [0] * 26
        for ch in s:
            count[ord(ch) - ord('a')] += 1

        best = n  # worst case: delete all characters

        # Try each possible target frequency f
        for f in range(1, n + 1):
            ops = 0
            possible = True
            for c in count:
                if c == 0:
                    # Need to insert f characters of this letter
                    ops += f
                else:
                    # Cost to change c to f: either delete or insert
                    if c < f:
                        ops += f - c
                    else:
                        ops += c - f
                if ops > best:
                    possible = False
                    break
            if possible and ops < best:
                best = ops

        return best
